namespace UnityWorld.Game.Domain;

/// <summary>自包含地图诊断页面；只呈现核心生成数据，不在浏览器重新生成世界。</summary>
public static class WorldMapPreview
{
    /// <summary>JSON 必须由默认安全转义的 System.Text.Json 产生。</summary>
    public static string Render(string json) => Template.Replace("__MAP_DATA__", json, StringComparison.Ordinal);

    private const string Template = """
<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
