<style>
:root{color-scheme:dark;--bg:#101918;--panel:#182421;--line:#30423b;--text:#e1e6d9;--muted:#9aa99b;--accent:#d6b779}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.6 system-ui,'Microsoft YaHei',sans-serif}header{height:88px;padding:18px 28px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);gap:20px}h1{margin:0;font:600 25px Georgia,'Noto Serif SC',serif;letter-spacing:6px}small,.muted{color:var(--muted)}.eyebrow{color:var(--accent);font-size:10px;letter-spacing:3px}.badge{border:1px solid #57654d;border-radius:20px;padding:4px 12px;color:var(--accent);font-size:12px}.stats{display:flex;gap:32px}.stats strong{display:block;font-size:19px;font-weight:500;font-variant-numeric:tabular-nums}.stats span{font-size:11px;color:var(--muted)}main{display:grid;grid-template-columns:minmax(0,1fr) 300px;height:calc(100vh - 88px)}.maparea{display:flex;flex-direction:column;min-width:0}.toolbar{padding:14px 20px;display:flex;gap:7px;align-items:center;flex-wrap:wrap;border-bottom:1px solid var(--line)}button,select{font:inherit;font-size:12px;color:var(--text);background:#21312b;border:1px solid #405347;border-radius:5px;padding:6px 10px;cursor:pointer}button:hover,button.active{background:#43543a;border-color:#a7a778;color:#fff}label{font-size:12px;color:var(--muted);margin-left:8px;cursor:pointer}input{accent-color:var(--accent)}#stage{position:relative;flex:1;overflow:hidden;background:radial-gradient(ellipse at 40% 40%,#24312b,#101918);touch-action:none}canvas{display:block;width:100%;height:100%;cursor:grab}canvas:active{cursor:grabbing}.compass{position:absolute;top:22px;left:24px;text-align:center;pointer-events:none;color:#d1c8ac;font:11px Georgia,serif}.compass b{font-size:25px;display:block}.hint{position:absolute;bottom:20px;left:24px;font-size:11px;color:#bac4b6;background:#14201be8;border:1px solid #405347;padding:6px 10px;border-radius:4px;pointer-events:none}.coords{position:absolute;bottom:20px;right:22px;color:#d6b779;font:12px monospace;pointer-events:none}.footer{padding:9px 20px;border-top:1px solid var(--line);display:flex;justify-content:space-between;font-size:11px;color:var(--muted);gap:12px}.sidebar{border-left:1px solid var(--line);background:var(--panel);overflow-y:auto;padding:20px}.section{border-bottom:1px solid var(--line);padding-bottom:18px;margin-bottom:18px}.section h2{font-size:12px;letter-spacing:2px;color:var(--accent);margin:0 0 12px}.tiletitle{font:600 23px Georgia,serif;margin:4px 0}.origin{font-size:12px;color:var(--muted)}dl{display:grid;grid-template-columns:80px 1fr;gap:5px;margin:15px 0 0;font-size:12px}dt{color:var(--muted)}dd{margin:0;overflow-wrap:anywhere}.meter{height:5px;background:#29382f;border-radius:3px;margin-top:4px}.meter i{height:100%;display:block;background:#a8b584;border-radius:3px}.env{display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;margin-top:17px;font-size:11px;color:var(--muted)}.env b{display:block;color:#d3dacb;font-size:13px;font-weight:500}.legend{display:grid;grid-template-columns:1fr 1fr;gap:6px;font-size:11px}.legend button{display:flex;align-items:center;gap:6px;background:transparent;border-color:transparent;padding:3px 0;text-align:left}.legend button.active{color:var(--accent)}.swatch{height:10px;width:10px;border-radius:2px;display:inline-block;flex-shrink:0}.warn{font-size:12px;color:#d1b583;margin:6px 0}#regions{width:100%;margin-bottom:8px}.info{font-size:12px;color:var(--muted)}code{font-size:10px;overflow-wrap:anywhere;color:#bac5af}#clear{font-size:11px;padding:3px 7px;float:right}@media(max-width:900px){main{grid-template-columns:1fr 240px}.stats{gap:14px}header{padding:16px}.sidebar{padding:14px}.stats strong{font-size:16px}}@media(max-width:620px){header{height:auto;align-items:start}.stats{display:none}main{height:calc(100vh - 85px);grid-template-columns:1fr}.sidebar{display:none}}
</style></head><body>
<header><div><div class="eyebrow">UNITYWORLD / WORLD ATLAS</div><h1>山河图谱</h1></div><span class="badge">地区拼图 · 初版</span><div class="stats"><div><strong>200 × 200</strong><span>大陆网格</span></div><div><strong id="seed"></strong><span>世界种子</span></div><div><strong id="coverage"></strong><span>地区覆盖率</span></div><div><strong id="regionCount"></strong><span>完整地区</span></div></div></header>
<main><div class="maparea"><div class="toolbar" id="layers"><button data-layer="terrain" class="active">地形</button><button data-layer="elevation">海拔</button><button data-layer="moisture">湿度</button><button data-layer="temperature">温度</button><button data-layer="source">生成来源</button><label><input id="outlines" type="checkbox" checked>地区轮廓</label><label><input id="rivers" type="checkbox" checked>水系</label><button id="fit">全图</button></div><div id="stage"><canvas id="map"></canvas><div class="compass">北<b>↑</b>N</div><div class="hint">拖动平移 · 滚轮缩放 · 点击查看土地</div><div class="coords" id="hover"></div></div><div class="footer"><span>西界长城 · 北境群山大漠 · 东海 · 南境雨林沙漠</span><span id="version"></span></div></div>
