<script>
'use strict';const D=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id),cells=D.cells,defs=D.types,byType=Object.fromEntries(defs.map(x=>[x.id,x])),W=D.width,H=D.height,R=5,SQ=Math.sqrt(3),pad=16;
let layer='terrain',selected=-1,typeFilter=null,regionFilter=null,scale=1,ox=0,oy=0,drag=null,moved=false;const canvas=$('map'),ctx=canvas.getContext('2d'),base=document.createElement('canvas');base.width=Math.ceil(SQ*R*(W+.5)+pad*2);base.height=Math.ceil(R*(1.5*H+.5)+pad*2);const b=base.getContext('2d');let outline=true,river=true;
const center=c=>[pad+SQ*R*(c.col+.5*(c.row&1)),pad+R*1.5*c.row];function hex(x,y,r=R){b.moveTo(x,y-r);for(let i=1;i<6;i++){const a=Math.PI/3*i-Math.PI/2;b.lineTo(x+r*Math.cos(a),y+r*Math.sin(a))}b.closePath()}
function color(c){let t=byType[c.typeId];if(layer==='source')return c.isFixed?'#ceab6c':c.source==='Region'?'#718e67':'#354e49';if(layer==='elevation'){let v=c.elevation;return `hsl(${125-v*100} 18% ${20+v*62}%)`}if(layer==='moisture')return `hsl(${38+c.moisture*154} ${22+c.moisture*25}% ${24+c.moisture*28}%)`;if(layer==='temperature')return `hsl(${215-c.temperature*205} 40% ${35+c.temperature*15}%)`;return t?.color||'#999'}
function rebuild(){b.clearRect(0,0,base.width,base.height);const groups=new Map;for(const c of cells){const col=color(c);if(!groups.has(col))groups.set(col,[]);groups.get(col).push(c)}for(const [col,items] of groups){b.beginPath();for(const c of items){const [x,y]=center(c);hex(x,y,R+.12)}b.fillStyle=col;b.fill()}
if(layer==='terrain'){b.globalAlpha=.12;for(const c of cells){if(c.elevation>.55&&!byType[c.typeId]?.tags?.includes('water')){const [x,y]=center(c);b.fillStyle=c.elevation>.8?'#fff':'#061c13';b.beginPath();b.moveTo(x-2,y+1.6);b.lineTo(x,y-2.5);b.lineTo(x+2,y+1.6);b.fill()}}b.globalAlpha=1}
if(river){b.strokeStyle=layer==='terrain'?'#86c8d0':'#a7dbe1';b.lineWidth=1.1;b.lineCap='round';b.beginPath();for(const c of cells){if(c.outDirection<0)continue;const dirs=[[1,0],[0,1],[-1,1],[-1,0],[0,-1],[1,-1]],v=dirs[c.outDirection],q=c.q+v[0],r=c.r+v[1],col=q+(r-(r&1))/2;if(col<0||col>=W||r<0||r>=H)continue;let [x,y]=center(c),[nx,ny]=center(cells[r*W+col]);b.moveTo(x,y);b.lineTo(nx,ny)}b.stroke()}
if(outline){b.strokeStyle='#e5d4a17a';b.lineWidth=.65;b.beginPath();for(const c of cells){if(c.regionIndex==null)continue;const [x,y]=center(c),dirs=[[1,0],[0,1],[-1,1],[-1,0],[0,-1],[1,-1]];for(let d=0;d<6;d++){const q=c.q+dirs[d][0],r=c.r+dirs[d][1],col=q+(r-(r&1))/2,n=(col>=0&&col<W&&r>=0&&r<H)?cells[r*W+col]:null;if(n?.regionIndex===c.regionIndex)continue;const a=d*Math.PI/3-Math.PI/6;b.moveTo(x+R*Math.cos(a),y+R*Math.sin(a));b.lineTo(x+R*Math.cos(a+Math.PI/3),y+R*Math.sin(a+Math.PI/3))}}b.stroke()}
for(const c of cells){if(c.landmark){const[x,y]=center(c);b.fillStyle='#f6e9b0';b.beginPath();b.arc(x,y,1.8,0,7);b.fill()}}
if(typeFilter||regionFilter!=null){b.fillStyle='#0b151cc9';b.beginPath();for(const c of cells)if((typeFilter&&c.typeId!==typeFilter)||(regionFilter!=null&&c.regionIndex!==regionFilter)){const[x,y]=center(c);hex(x,y,R+.1)}b.fill()}
draw()}
function draw(){const dpr=devicePixelRatio||1;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,canvas.width/dpr,canvas.height/dpr);ctx.save();ctx.translate(ox,oy);ctx.scale(scale,scale);ctx.drawImage(base,0,0);if(selected>=0){const [x,y]=center(cells[selected]);ctx.strokeStyle='#fff3c8';ctx.lineWidth=2/scale;ctx.beginPath();for(let i=0;i<=6;i++){const a=i*Math.PI/3-Math.PI/2;i?ctx.lineTo(x+R*Math.cos(a),y+R*Math.sin(a)):ctx.moveTo(x,y-R)}ctx.stroke()}ctx.restore()}
function fit(){scale=Math.min(canvas.clientWidth/base.width,canvas.clientHeight/base.height)*.96;ox=(canvas.clientWidth-base.width*scale)/2;oy=(canvas.clientHeight-base.height*scale)/2;draw()}function resize(){canvas.width=canvas.clientWidth*(devicePixelRatio||1);canvas.height=canvas.clientHeight*(devicePixelRatio||1);fit()}new ResizeObserver(resize).observe($('stage'));
function pick(e){const box=canvas.getBoundingClientRect(),x=(e.clientX-box.left-ox)/scale,y=(e.clientY-box.top-oy)/scale,rr=Math.round((y-pad)/(R*1.5));let best=-1,dist=Infinity;for(let r=rr-1;r<=rr+1;r++){if(r<0||r>=H)continue;const cc=Math.round((x-pad)/(SQ*R)-.5*(r&1));for(let col=cc-1;col<=cc+1;col++){if(col<0||col>=W)continue;const i=r*W+col,[xx,yy]=center(cells[i]),dd=(xx-x)**2+(yy-y)**2;if(dd<dist){best=i;dist=dd}}}return dist<=R*R*1.3?best:-1}
function row(dl,k,v){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=k;dd.textContent=v;dl.append(dt,dd)}function detail(i){if(i<0)return;selected=i;const c=cells[i],t=byType[c.typeId],reg=D.regions.find(r=>r.index===c.regionIndex),div=$('detail');div.replaceChildren();const title=document.createElement('div');title.className='tiletitle';title.textContent=t?.name||c.typeId;const origin=document.createElement('div');origin.className='origin';origin.textContent=c.isFixed?'固定锚点地区':({Region:'作者地区拼图',Fill:'基础地块填充'})[c.source];div.append(title,origin);const dl=document.createElement('dl');row(dl,'坐标',`${c.col}, ${c.row} / Axial ${c.q}, ${c.r}`);row(dl,'所属地区',reg?`${reg.name} #${reg.index}`:'无');row(dl,'地标',c.landmark||'无');row(dl,'水文',c.isSink?'水系终点':c.outDirection>=0?`向${['东','东南','西南','西','西北','东北'][c.outDirection]}流${c.isSource?' · 源头':''}`:'格内环境');row(dl,'通行',c.blockAll?'禁止通行':(c.movement||t?.movement||[]).join(' / ')||'无');if(c.source==='Fill'){row(dl,'候选类型',String(c.candidateCount));row(dl,'选中权重',Number(c.selectedWeight).toFixed(3))}div.append(dl);const en=document.createElement('div');en.className='env';for(const[k,label]of[['elevation','海拔'],['moisture','湿度'],['temperature','温度']]){const d=document.createElement('div');d.textContent=label;const v=document.createElement('b');v.textContent=(c[k]*100).toFixed(0)+'%';const m=document.createElement('div');m.className='meter';const fill=document.createElement('i');fill.style.width=(c[k]*100)+'%';m.append(fill);d.append(v,m);en.append(d)}div.append(en);if(c.fillCandidates?.length){const wrap=document.createElement('details'),head=document.createElement('summary');head.textContent='填充候选与权重';wrap.style.fontSize='11px';wrap.style.marginTop='15px';wrap.append(head);for(const fc of c.fillCandidates){const line=document.createElement('div');line.style.margin='5px 0';line.textContent=`${byType[fc.typeId]?.name||fc.typeId}：${fc.baseWeight.toFixed(2)} × ${fc.environmentWeight.toFixed(3)} × ${fc.adjacencyWeight.toFixed(2)} = ${fc.finalWeight.toFixed(3)}${fc.rejectedByLookahead?'（邻格前瞻拒绝）':''}`;wrap.append(line)}div.append(wrap)}draw()}
canvas.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY,ox,oy};moved=false;canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(drag){const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>4)moved=true;ox=drag.ox+dx;oy=drag.oy+dy;draw()}const i=pick(e);$('hover').textContent=i<0?'':`${cells[i].col}, ${cells[i].row} · ${byType[cells[i].typeId]?.name||cells[i].typeId}`});canvas.addEventListener('pointerup',e=>{if(!moved)detail(pick(e));drag=null});canvas.addEventListener('pointercancel',()=>drag=null);canvas.addEventListener('wheel',e=>{e.preventDefault();const box=canvas.getBoundingClientRect(),x=e.clientX-box.left,y=e.clientY-box.top,f=Math.exp(-e.deltaY*.001),ns=Math.max(.15,Math.min(12,scale*f));ox=x-(x-ox)*ns/scale;oy=y-(y-oy)*ns/scale;scale=ns;draw()},{passive:false});
$('layers').addEventListener('click',e=>{const l=e.target.dataset.layer;if(!l)return;layer=l;document.querySelectorAll('[data-layer]').forEach(x=>x.classList.toggle('active',x.dataset.layer===l));rebuild()});$('outlines').onchange=e=>{outline=e.target.checked;rebuild()};$('rivers').onchange=e=>{river=e.target.checked;rebuild()};$('fit').onclick=fit;$('clear').onclick=()=>{typeFilter=null;regionFilter=null;$('regions').value='';document.querySelectorAll('#legend button').forEach(x=>x.classList.remove('active'));rebuild()};
for(const t of defs){const button=document.createElement('button'),sw=document.createElement('span');sw.className='swatch';sw.style.background=t.color;button.append(sw,document.createTextNode(t.name));button.onclick=()=>{typeFilter=typeFilter===t.id?null:t.id;document.querySelectorAll('#legend button').forEach(x=>x.classList.remove('active'));button.classList.toggle('active',typeFilter===t.id);rebuild()};$('legend').append(button)}
for(const r of D.regions){const o=document.createElement('option');o.value=r.index;o.textContent=`${r.name} #${r.index} · ${r.cellCount}格`;$('regions').append(o)}$('regions').onchange=e=>{regionFilter=e.target.value===''?null:Number(e.target.value);typeFilter=null;rebuild();if(regionFilter!=null){const r=D.regions.find(x=>x.index===regionFilter),list=cells.filter(x=>x.regionIndex===regionFilter),cx=list.reduce((n,c)=>n+center(c)[0],0)/list.length,cy=list.reduce((n,c)=>n+center(c)[1],0)/list.length;scale=Math.min(5,Math.max(2,scale));ox=canvas.clientWidth/2-cx*scale;oy=canvas.clientHeight/2-cy*scale;$('regionInfo').textContent=`${r.name}：${r.cellCount}格完整固定布局，适配分数 ${r.score.toFixed(3)}`;detail(cells.indexOf(list[0]))}};
$('seed').textContent=D.seed;$('coverage').textContent=(D.coverage*100).toFixed(1)+'%';$('regionCount').textContent=D.regions.length;$('version').textContent=D.version;const report=$('report');for(const text of [`类型 ${defs.length} · 固定地区 ${D.boundaryCount} 格`,`水系 ${D.riverCount} 格 · 生成 ${(D.elapsedMs/1000).toFixed(2)} 秒`,`种子 ${D.seed} · ${D.profile}`]){const p=document.createElement('div');p.textContent=text;report.append(p)}for(const warning of D.warnings){const p=document.createElement('p');p.className='warn';p.textContent=warning;report.append(p)}const hash=document.createElement('code');hash.textContent='结构 '+D.structureHash.slice(0,24);report.append(hash);rebuild();resize();window.mapAtlas={data:D,selectCell:detail,fit};
